SELECT id, device_code, reading_ts, humidity, firmware, MAX(temp_c) OVER w_recent AS running_max_temp_c, AVG(temp_c) OVER w_recent AS running_avg_temp_c, MIN(temp_c) OVER w_recent AS running_min_temp_c, COUNT(temp_c) OVER w_recent AS running_count_temp_c FROM device_readings WINDOW w_recent AS (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
